    'RegisterSimpleRisk'=>'Регистрирайте SimpleRisk',
    'RegistrationText'=>'Регистрираните екземпляри на SimpleRisk незабавно получават достъп до надстройката и екстрите на Secure Controls Framework (SCF). Надстройката Extra предоставя възможност за архивиране и надграждане на вашия екземпляр на SimpleRisk с едно натискане на бутон. Secure Controls Framework (SCF) Extra предоставя обща контролна рамка, която е интегрирана във функционалността на SimpleRisk Governance. След като регистрирате SimpleRisk, вашата регистрационна информация ще бъде изпратена до сървър, хостван от SimpleRisk. Предоставената информация за регистрация ще бъде използвана от SimpleRisk за уведомяване на клиентите за нови версии и актуализации за сигурност. Актът на регистриране на SimpleRisk ще ви включи в нашите маркетингови съобщения, но можете да се откажете по всяко време, като използвате връзката за отписване в тези съобщения. SimpleRisk зачита поверителността на нашите клиенти и информацията, предоставена ни чрез процеса на регистрация на SimpleRisk, никога няма да бъде продадена на трета страна.',
