    'RiskConfigurationDesc'               => 'Конфигурирайте правила за оценка на риска: нива, апетит, прагове на SLA и класически/допринасящи формули за риск.',
    'RiskAndThreatCatalogDesc'            => 'Поддържайте каталога със стойности на риска и заплахата, използвани в падащите менюта.',
